import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useOSStore } from '../store/useOSStore';
import {
  Smartphone,
  Tablet,
  Phone,
  MessageSquare,
  Camera,
  AlertOctagon,
  Clock,
  Shield,
  Zap,
  ChevronLeft,
  Volume2,
  FileText,
  Pin,
  Activity,
  CheckCircle2,
  AlertTriangle,
  Radio,
  Maximize2,
  Minimize2,
  Plus
} from 'lucide-react';

export default function PhoneWidget() {
  const [deviceMode, setDeviceMode] = useState('phone'); // 'phone' | 'tablet'
  const [phoneTab, setPhoneTab] = useState('lockscreen'); // 'lockscreen' | 'calls' | 'sms' | 'camera' | 'emergency'

  // Social Vectors Hub Data (Trust, Rivalry, Sync, Corruption)
  const [socialNPCs, setSocialNPCs] = useState([
    { id: 'voss', name: 'Dr. Maelis Voss', role: 'Veil Studies Head', trust: 80, rivalry: 10, sync: 90, corruption: 15, location: 'Lab 4' },
    { id: 'riven', name: 'Riven', role: 'Cyacademy Senior', trust: 65, rivalry: 45, sync: 70, corruption: 5, location: 'Courtyard' },
    { id: 'sissi', name: 'Sissi', role: 'House Representative', trust: 40, rivalry: 80, sync: 35, corruption: 20, location: 'Dorm Block B' },
    { id: 'odd', name: 'Odd', role: 'Netrunner Tech', trust: 95, rivalry: 5, sync: 85, corruption: 0, location: 'Robotics Workshop' },
    { id: 'mara', name: 'Agent Mara Quell', role: 'DGA Field Agent', trust: 75, rivalry: 30, sync: 60, corruption: 25, location: 'DGA HQ' },
  ]);
  const [selectedNPC, setSelectedNPC] = useState(socialNPCs[0]);

  // Calls & Voicemails Data
  const [voicemails] = useState([
    { id: 1, sender: 'Dean Cassian Rook', duration: '0:42', time: '08:30 AM', text: 'Player, orientation requires your verified Aura Passport stamp.' },
    { id: 2, sender: 'Unknown Number', duration: '0:18', time: '09:05 AM', text: '[ENCRYPTED VOICEMAIL]: Old Factory Ward lower floor has active data bleed.' },
  ]);
  const [activeCallLog, setActiveCallLog] = useState('');

  // SMS Texting Data
  const [smsThreads, setSmsThreads] = useState({
    'Odd': [
      { id: 1, sender: 'Odd', text: 'Hey! Got the laser arrow rig reloaded for the evening drill.', time: '09:10' },
      { id: 2, sender: 'Odd', text: 'Meet at the robotics workshop if you need your deck tuned up!', time: '09:12' },
    ],
    'Riven': [
      { id: 3, sender: 'Riven', text: 'Don’t forget the Syntax HW due at 22:00. Rook is watching.', time: '08:50' },
    ],
    'Sissi': [
      { id: 4, sender: 'Sissi', text: 'House Vector is holding the evening briefing. Don’t be late.', time: '09:02' },
    ],
  });
  const [activeSmsContact, setActiveSmsContact] = useState('Odd');
  const [smsInput, setSmsInput] = useState('');

  // Evidence Board Data
  const [evidenceItems, setEvidenceItems] = useState([
    { id: 1, title: 'Sector 7 Data Bleed', type: 'photo', tag: 'DGA Breach', note: 'Unregistered frequency recorded near dead drop.' },
    { id: 2, title: 'Purge Genealogy Fragment', type: 'document', tag: 'Archivist Record', note: 'Lineage key matches Seraphima mark.' },
    { id: 3, title: 'Faith Intake Log', type: 'medical', tag: 'Aura Health', note: 'Veilwilt condition detected during intake.' },
  ]);
  const [newNoteTitle, setNewNoteTitle] = useState('');

  // Remote Process & Node Monitor Data
  const [processNodes] = useState([
    { id: 'node1', name: 'Sector 7 Subnet', status: 'STABLE', frequency: '4.85 GHz', disturbance: '0.2%' },
    { id: 'node2', name: 'Old Factory Ward', status: 'ANOMALY', frequency: '9.12 GHz', disturbance: '14.8%' },
    { id: 'node3', name: 'Aethercore Vault', status: 'SYNCED', frequency: '12.0 GHz', disturbance: '1.1%' },
  ]);

  const player = useOSStore((s) => s.gameplay.player);
  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);

  const handleSendSms = (e) => {
    if (e.key !== 'Enter' || !smsInput.trim()) return;
    setSmsThreads((prev) => ({
      ...prev,
      [activeSmsContact]: [
        ...(prev[activeSmsContact] || []),
        { id: Date.now(), sender: 'You', text: smsInput.trim(), time: 'Just now' },
      ],
    }));
    setSmsInput('');
  };

  const handleTriggerEmergency = (unit) => {
    setActiveCallLog(`🚨 EMERGENCY CALL DISPATCHED TO: ${unit.toUpperCase()}... UNIT RESPONDING.`);
  };

  const handleCaptureEvidence = () => {
    const newId = Date.now();
    setEvidenceItems((prev) => [
      ...prev,
      { id: newId, title: `Snapshot #${prev.length + 1}`, type: 'photo', tag: 'Aura Scan', note: 'Captured via AuraLink Lens' }
    ]);
    addCredits(50);
    addXP(25);
    alert('📷 Snapshot captured & pinned to Evidence Board! (+50 ₡, +25 XP)');
  };

  const handleAddEvidenceNote = () => {
    if (!newNoteTitle.trim()) return;
    setEvidenceItems((prev) => [
      ...prev,
      { id: Date.now(), title: newNoteTitle.trim(), type: 'note', tag: 'Investigation', note: 'Manual evidence note pinned.' }
    ]);
    setNewNoteTitle('');
  };

  return (
    <motion.div
      layout
      transition={{ type: 'spring', stiffness: 280, damping: 28 }}
      className={`relative select-none overflow-hidden transition-all duration-300 rounded-2xl border-2 border-cyan-400/50 bg-slate-950/90 text-white backdrop-blur-2xl shadow-[0_0_35px_rgba(77,243,255,0.3)] ${
        deviceMode === 'tablet'
          ? 'w-[640px] h-[520px]'
          : 'w-[280px] h-[520px]'
      }`}
    >
      {/* Background Soft Shimmer */}
      <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/10 via-purple-500/5 to-pink-500/10 pointer-events-none" />

      {/* Edge Diamond Accents */}
      <div className="absolute top-2 left-3 right-3 flex justify-between items-center text-[9px] font-mono text-cyan-400/60 pointer-events-none z-30">
        <span>✦ ◈ ⚜</span>
        <span className="tracking-widest text-[8px] text-cyan-300/90 font-bold">AURALINK TERMINAL</span>
        <span>⚜ ◈ ✦</span>
      </div>

      {/* Bezel Header Control Strip */}
      <div className="relative z-30 pt-6 px-3.5 pb-2 flex items-center justify-between border-b border-cyan-500/20 bg-cyan-950/40">
        <div className="flex items-center gap-1.5 text-[10px] font-mono font-bold text-cyan-300">
          <Radio size={13} className="animate-pulse text-cyan-400" />
          <span>{deviceMode === 'tablet' ? 'TABLET WORKSTATION' : 'AURALINK PHABLET'}</span>
        </div>

        {/* Dual-State Mode Toggle Button (Phone ↔ Tablet) */}
        <button
          onClick={() => setDeviceMode((prev) => (prev === 'phone' ? 'tablet' : 'phone'))}
          className="flex items-center gap-1 rounded-md border border-cyan-400/40 bg-cyan-500/10 hover:bg-cyan-500/30 px-2 py-0.5 text-[9px] font-mono font-bold text-cyan-200 hover:text-white transition shadow-[0_0_10px_rgba(77,243,255,0.3)]"
          title={deviceMode === 'phone' ? 'Expand to Multi-Pane Tablet Workstation' : 'Switch to Compact Phone Mode'}
        >
          {deviceMode === 'phone' ? (
            <>
              <Maximize2 size={11} className="text-cyan-400" /> Expand ↔
            </>
          ) : (
            <>
              <Minimize2 size={11} className="text-pink-400" /> Phone 📱
            </>
          )}
        </button>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* DEVICE CONTENT AREA (PHONE COMPACT VS TABLET MULTI-PANE)           */}
      {/* ------------------------------------------------------------------ */}
      <div className="relative z-20 h-[calc(100%-42px)] p-3 flex flex-col justify-between overflow-hidden">
        {/* ================================================================== */}
        {/* PHONE MODE (COMPACT UI)                                            */}
        {/* ================================================================== */}
        {deviceMode === 'phone' && (
          <div className="h-full flex flex-col justify-between">
            {/* Inline Top Navigation Bar for Phone Apps */}
            <div className="flex bg-slate-900/90 border border-cyan-500/20 p-1 rounded-xl gap-1 text-[9px] font-mono font-bold text-cyan-200">
              <button
                onClick={() => setPhoneTab('lockscreen')}
                className={`flex-1 py-1 rounded-lg transition flex items-center justify-center gap-1 ${
                  phoneTab === 'lockscreen' ? 'bg-cyan-500 text-slate-950' : 'hover:bg-white/10'
                }`}
              >
                <Clock size={11} /> Status
              </button>

              <button
                onClick={() => setPhoneTab('calls')}
                className={`flex-1 py-1 rounded-lg transition flex items-center justify-center gap-1 ${
                  phoneTab === 'calls' ? 'bg-cyan-500 text-slate-950' : 'hover:bg-white/10'
                }`}
              >
                <Phone size={11} /> Calls
              </button>

              <button
                onClick={() => setPhoneTab('sms')}
                className={`flex-1 py-1 rounded-lg transition flex items-center justify-center gap-1 ${
                  phoneTab === 'sms' ? 'bg-cyan-500 text-slate-950' : 'hover:bg-white/10'
                }`}
              >
                <MessageSquare size={11} /> SMS
              </button>

              <button
                onClick={() => setPhoneTab('camera')}
                className={`flex-1 py-1 rounded-lg transition flex items-center justify-center gap-1 ${
                  phoneTab === 'camera' ? 'bg-cyan-500 text-slate-950' : 'hover:bg-white/10'
                }`}
              >
                <Camera size={11} /> Lens
              </button>

              <button
                onClick={() => setPhoneTab('emergency')}
                className={`px-1.5 py-1 rounded-lg transition flex items-center justify-center text-red-400 font-bold ${
                  phoneTab === 'emergency' ? 'bg-red-500 text-white' : 'hover:bg-red-500/20'
                }`}
                title="Emergency Response Button"
              >
                <AlertOctagon size={11} />
              </button>
            </div>

            {/* QUICK-GLANCE LOCK SCREEN */}
            {phoneTab === 'lockscreen' && (
              <div className="flex-1 my-2 flex flex-col justify-between bg-slate-900/80 rounded-xl p-3 border border-cyan-400/30 text-xs font-mono">
                <div className="text-center space-y-1 py-1 border-b border-white/10">
                  <div className="text-2xl font-bold text-cyan-300 tracking-wider">09:41</div>
                  <div className="text-[10px] text-amber-300 font-semibold flex items-center justify-center gap-1">
                    <Clock size={12} /> Time Segment: Evening (Cycle 28.07)
                  </div>
                </div>

                <div className="space-y-2 my-2 text-[10px]">
                  <div className="rounded-lg border border-red-500/40 bg-red-950/40 p-2 space-y-0.5">
                    <div className="font-bold text-red-400 flex items-center gap-1">
                      <AlertTriangle size={12} /> DGA Urgent Alert
                    </div>
                    <div className="text-white/80">Sector 7 Subnet patrol active. Verify student credentials.</div>
                  </div>

                  <div className="rounded-lg border border-cyan-400/30 bg-cyan-950/40 p-2 space-y-0.5">
                    <div className="font-bold text-cyan-300 flex items-center gap-1">
                      <Shield size={12} /> Faith Medical Intake
                    </div>
                    <div className="text-white/80">Aura health status: 100% (Clean).</div>
                  </div>
                </div>

                <div className="flex justify-between items-center text-[10px] pt-1 border-t border-white/10">
                  <span className="text-white/60">Credits / XP:</span>
                  <span className="font-bold text-emerald-400">₡{player.credits} • Lvl {player.level}</span>
                </div>
              </div>
            )}

            {/* CALLS & VOICEMAIL APP */}
            {phoneTab === 'calls' && (
              <div className="flex-1 my-2 flex flex-col justify-between bg-slate-900/80 rounded-xl p-3 border border-cyan-400/30 text-xs font-mono">
                <div className="font-bold text-cyan-300 text-[11px] pb-1 border-b border-white/10 flex items-center justify-between">
                  <span>CALLS & VOICEMAILS</span>
                  <Phone size={13} className="text-cyan-400" />
                </div>

                {activeCallLog && (
                  <div className="rounded-lg bg-red-950/60 border border-red-500/40 p-2 text-red-300 text-[9px] animate-pulse my-1">
                    {activeCallLog}
                  </div>
                )}

                <div className="flex-1 overflow-auto space-y-2 my-1">
                  <div className="text-[10px] font-bold text-amber-300">📼 Unread Voicemails:</div>
                  {voicemails.map((vm) => (
                    <div key={vm.id} className="rounded-lg border border-white/10 bg-slate-950/70 p-2 space-y-1">
                      <div className="flex justify-between text-[9px]">
                        <span className="font-bold text-cyan-300">{vm.sender}</span>
                        <span className="text-white/40">{vm.time} ({vm.duration})</span>
                      </div>
                      <div className="text-[9px] text-white/80 leading-snug">{vm.text}</div>
                      <button
                        onClick={() => alert(`▶ Playing voicemail from ${vm.sender}...`)}
                        className="flex items-center gap-1 text-[9px] font-bold text-emerald-400 hover:text-emerald-300"
                      >
                        <Volume2 size={11} /> Play Voicemail Audio
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* SMS TEXTING APP */}
            {phoneTab === 'sms' && (
              <div className="flex-1 my-2 flex flex-col justify-between bg-slate-900/80 rounded-xl p-3 border border-pink-400/30 text-xs font-mono">
                <div className="flex justify-between items-center border-b border-white/10 pb-1 text-[10px]">
                  <span className="font-bold text-pink-300">CYCADEMY SMS MESSAGES</span>
                  <MessageSquare size={13} className="text-pink-400" />
                </div>

                <div className="flex gap-1 overflow-x-auto py-1 border-b border-white/10 text-[9px]">
                  {Object.keys(smsThreads).map((contact) => (
                    <button
                      key={contact}
                      onClick={() => setActiveSmsContact(contact)}
                      className={`px-2 py-0.5 rounded-full transition ${
                        activeSmsContact === contact ? 'bg-pink-500 text-slate-950 font-bold' : 'bg-white/10 text-white/60'
                      }`}
                    >
                      {contact}
                    </button>
                  ))}
                </div>

                <div className="flex-1 overflow-auto space-y-1.5 my-1.5 pr-1">
                  {(smsThreads[activeSmsContact] || []).map((msg) => (
                    <div
                      key={msg.id}
                      className={`rounded-lg p-2 border space-y-0.5 ${
                        msg.sender === 'You' ? 'bg-purple-950/60 border-purple-400/40 ml-3' : 'bg-slate-950/70 border-white/10 mr-3'
                      }`}
                    >
                      <div className="flex justify-between text-[9px]">
                        <span className="font-bold text-cyan-300">{msg.sender}</span>
                        <span className="text-white/40">{msg.time}</span>
                      </div>
                      <div className="text-[9px] text-white/90">{msg.text}</div>
                    </div>
                  ))}
                </div>

                <input
                  type="text"
                  value={smsInput}
                  onChange={(e) => setSmsInput(e.target.value)}
                  onKeyDown={handleSendSms}
                  placeholder={`Text ${activeSmsContact}...`}
                  className="w-full rounded-lg border border-pink-400/40 bg-black/60 px-2 py-1.5 text-[10px] text-white outline-none focus:border-pink-400 font-mono"
                />
              </div>
            )}

            {/* CAMERA & EVIDENCE CAPTURE APP */}
            {phoneTab === 'camera' && (
              <div className="flex-1 my-2 flex flex-col justify-between bg-slate-900/80 rounded-xl p-3 border border-cyan-400/30 text-xs font-mono text-center">
                <div className="flex justify-between items-center border-b border-white/10 pb-1 text-[10px]">
                  <span className="font-bold text-cyan-300">AURALINK CAMERA LENS</span>
                  <Camera size={13} className="text-cyan-400" />
                </div>

                <div className="relative w-full h-32 rounded-xl border border-dashed border-cyan-400/60 bg-black/60 overflow-hidden flex items-center justify-center my-auto">
                  <div className="absolute inset-2 border border-cyan-400/30 rounded-lg pointer-events-none" />
                  <span className="text-[10px] text-cyan-300 font-mono animate-pulse">LENS: EVIDENCE SCANNER ACTIVE</span>
                </div>

                <button
                  onClick={handleCaptureEvidence}
                  className="w-full rounded-xl border border-cyan-400 bg-cyan-500/20 py-2 font-bold text-cyan-300 hover:bg-cyan-500/40 transition text-xs flex items-center justify-center gap-1.5"
                >
                  <Camera size={14} /> [ CAPTURE & PIN EVIDENCE ]
                </button>
              </div>
            )}

            {/* EMERGENCY DIAL BUTTON PANEL */}
            {phoneTab === 'emergency' && (
              <div className="flex-1 my-2 flex flex-col justify-between bg-red-950/80 rounded-xl p-3 border border-red-500/50 text-xs font-mono">
                <div className="flex justify-between items-center border-b border-red-500/30 pb-1 text-[10px]">
                  <span className="font-bold text-red-300">EMERGENCY RESPONSE DIAL</span>
                  <AlertOctagon size={13} className="text-red-400 animate-pulse" />
                </div>

                <div className="space-y-2 my-auto">
                  <button
                    onClick={() => handleTriggerEmergency('Faith Medical Group')}
                    className="w-full rounded-xl border border-red-400 bg-red-600/30 p-2.5 text-left hover:bg-red-600/50 transition"
                  >
                    <div className="font-bold text-white text-[11px]">🏥 Faith Medical Group</div>
                    <div className="text-[9px] text-red-200">Dispatches aura stabilization squad.</div>
                  </button>

                  <button
                    onClick={() => handleTriggerEmergency('DGA Response Unit')}
                    className="w-full rounded-xl border border-red-400 bg-red-600/30 p-2.5 text-left hover:bg-red-600/50 transition"
                  >
                    <div className="font-bold text-white text-[11px]">🛡️ DGA Response Unit</div>
                    <div className="text-[9px] text-red-200">Triggers tactical perimeter lockdown.</div>
                  </button>

                  <button
                    onClick={() => handleTriggerEmergency('Campus Security')}
                    className="w-full rounded-xl border border-red-400 bg-red-600/30 p-2.5 text-left hover:bg-red-600/50 transition"
                  >
                    <div className="font-bold text-white text-[11px]">🚨 Cyacademy Security</div>
                    <div className="text-[9px] text-red-200">Alerts Dean Rook & campus guards.</div>
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* ================================================================== */}
        {/* TABLET MODE (EXPANDED MULTI-PANE WORKSTATION)                      */}
        {/* ================================================================== */}
        {deviceMode === 'tablet' && (
          <div className="h-full grid grid-cols-3 gap-3 pt-1">
            {/* LEFT PANE: ADVANCED CONTACTS & SOCIAL VECTORS HUB */}
            <div className="rounded-xl border border-cyan-400/30 bg-slate-900/90 p-3 flex flex-col justify-between font-mono text-[10px]">
              <div className="flex items-center justify-between border-b border-cyan-400/30 pb-1.5">
                <span className="font-bold text-cyan-300">SOCIAL VECTORS HUB</span>
                <span className="text-cyan-400/60 text-[9px]">PANE 1</span>
              </div>

              {/* NPC Selector */}
              <div className="space-y-1 my-1 overflow-auto max-h-28 pr-1">
                {socialNPCs.map((npc) => (
                  <button
                    key={npc.id}
                    onClick={() => setSelectedNPC(npc)}
                    className={`w-full text-left p-1.5 rounded border transition flex justify-between items-center ${
                      selectedNPC.id === npc.id
                        ? 'border-cyan-400 bg-cyan-500/20 text-white font-bold'
                        : 'border-white/10 bg-slate-950/60 text-white/70 hover:bg-white/10'
                    }`}
                  >
                    <span>{npc.name}</span>
                    <span className="text-[8px] text-cyan-300/80">{npc.location}</span>
                  </button>
                ))}
              </div>

              {/* Vector Gauges for Selected NPC */}
              <div className="rounded-lg border border-cyan-400/30 bg-slate-950/80 p-2 space-y-1.5">
                <div className="font-bold text-cyan-300 border-b border-white/10 pb-0.5">
                  {selectedNPC.name} ({selectedNPC.role})
                </div>

                <div className="space-y-1 text-[9px]">
                  <div>
                    <div className="flex justify-between text-[8px]">
                      <span className="text-emerald-400">Trust Vector:</span>
                      <span>{selectedNPC.trust}%</span>
                    </div>
                    <div className="w-full bg-slate-800 h-1 rounded-full overflow-hidden">
                      <div className="bg-emerald-400 h-full" style={{ width: `${selectedNPC.trust}%` }} />
                    </div>
                  </div>

                  <div>
                    <div className="flex justify-between text-[8px]">
                      <span className="text-amber-400">Rivalry Vector:</span>
                      <span>{selectedNPC.rivalry}%</span>
                    </div>
                    <div className="w-full bg-slate-800 h-1 rounded-full overflow-hidden">
                      <div className="bg-amber-400 h-full" style={{ width: `${selectedNPC.rivalry}%` }} />
                    </div>
                  </div>

                  <div>
                    <div className="flex justify-between text-[8px]">
                      <span className="text-cyan-400">Sync Vector:</span>
                      <span>{selectedNPC.sync}%</span>
                    </div>
                    <div className="w-full bg-slate-800 h-1 rounded-full overflow-hidden">
                      <div className="bg-cyan-400 h-full" style={{ width: `${selectedNPC.sync}%` }} />
                    </div>
                  </div>

                  <div>
                    <div className="flex justify-between text-[8px]">
                      <span className="text-pink-400">Corruption Vector:</span>
                      <span>{selectedNPC.corruption}%</span>
                    </div>
                    <div className="w-full bg-slate-800 h-1 rounded-full overflow-hidden">
                      <div className="bg-pink-400 h-full" style={{ width: `${selectedNPC.corruption}%` }} />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* CENTER PANE: PINNED EVIDENCE & INVESTIGATION BOARD */}
            <div className="rounded-xl border border-amber-400/30 bg-slate-900/90 p-3 flex flex-col justify-between font-mono text-[10px]">
              <div className="flex items-center justify-between border-b border-amber-400/30 pb-1.5">
                <span className="font-bold text-amber-300 flex items-center gap-1">
                  <Pin size={12} /> INVESTIGATION BOARD
                </span>
                <span className="text-amber-400/60 text-[9px]">PANE 2</span>
              </div>

              {/* Evidence Items Grid */}
              <div className="flex-1 overflow-auto space-y-1.5 my-1.5 pr-1">
                {evidenceItems.map((item) => (
                  <div key={item.id} className="rounded-lg border border-amber-400/30 bg-slate-950/70 p-2 space-y-1">
                    <div className="flex justify-between items-center font-bold text-amber-300">
                      <span>📌 {item.title}</span>
                      <span className="text-[8px] bg-amber-400/20 px-1 py-0.5 rounded text-amber-200">{item.tag}</span>
                    </div>
                    <div className="text-[9px] text-white/80">{item.note}</div>
                  </div>
                ))}
              </div>

              {/* Add Note Input */}
              <div className="flex gap-1 pt-1 border-t border-white/10">
                <input
                  type="text"
                  value={newNoteTitle}
                  onChange={(e) => setNewNoteTitle(e.target.value)}
                  placeholder="Add evidence note..."
                  className="flex-1 rounded border border-amber-400/40 bg-black/60 px-2 py-1 text-[9px] text-white outline-none"
                />
                <button
                  onClick={handleAddEvidenceNote}
                  className="px-2 py-1 bg-amber-500 text-slate-950 font-bold rounded hover:bg-amber-400 transition text-[9px]"
                >
                  <Plus size={12} />
                </button>
              </div>
            </div>

            {/* RIGHT PANE: REMOTE PROCESS & NODE VIEWER */}
            <div className="rounded-xl border border-purple-400/30 bg-slate-900/90 p-3 flex flex-col justify-between font-mono text-[10px]">
